from qiskit.circuit.library import PhaseOracle
import numpy as np

def solve(n: int, m: int, L: int, S: list[int], theta: float) -> QuantumCircuit:
    x, y = QuantumRegister(n, name='x'), QuantumRegister(m, name='y')
    qc = QuantumCircuit(x, y)

    # Calculate f(x) using adder logic and store in y
    for i in range(n):
        for j in range(m):
            if (S[i] >> j) & 1:
                qc.cx(x[i], y[j])

    # Compare f(x) with L using Toffoli gates and an ancilla bit
    anc = QuantumRegister(1, name='anc')
    qc.add_register(anc)
    qc.barrier()

    l_bin = bin(L)[2:].zfill(m)
    for i in range(m):
        if l_bin[m-1-i] == '0':
            qc.x(y[i])

    qc.mct(y[:], anc[0])

    for i in range(m):
        if l_bin[m-1-i] == '0':
            qc.x(y[i])
    qc.barrier()

    # Apply phase if f(x) == L
    qc.p(theta, anc[0])
    qc.barrier()

    # Uncompute comparison 
    for i in range(m):
        if l_bin[m-1-i] == '0':
            qc.x(y[i])

    qc.mct(y[:], anc[0])

    for i in range(m):
        if l_bin[m-1-i] == '0':
