    # Apply g(m_after, k_after)
    for _ in range(k_after):
        qc.append(QFT(num_qubits=n, inverse=True).control(), [n] + list(range(n)))
    if m_after == 1:
        qc.append(QFT(num_qubits=n).control(), [n] + list(range(n)))

    return qc

